/// Runs the ChatGPT OAuth flow and saves the resulting credentials.
Future<void> _handleChatGptOAuthCommand({
  required bool headless,
  bool noBrowser = false,
}) async {
  if (_providerFlowActive) return;
  _providerFlowActive = true;
  try {
    await _runChatGptOAuthCommand(headless: headless, noBrowser: noBrowser);
  } finally {
    _providerFlowActive = false;
    _promptLineBuffer.clear();
  }
}

Future<void> _runChatGptOAuthCommand({
  required bool headless,
  bool noBrowser = false,
}) async {
  final spec = providerCatalog['chatgpt']!;

  // Existing ChatGPT accounts first: pick one to switch to, or sign in
  // again. One identity per auth domain (#1706): the sign-in re-auths
  // THE domain record (a typed name renames it) — it never mints a
  // second entry. The headless variant skips the picker: it is the
  // scripted sign-in form (its stdin carries the redirect URL);
  // saved accounts switch via `/provider <name>`.
  if (!headless) {
    final registry = config.customProviders;
    final accounts = [
      for (final entry in registry?.entries ?? const <CustomProviderEntry>[])
        if (entry.apiType == spec.name) entry,
    ];
    if (accounts.isNotEmpty) {
      final choice = await _pickOption('ChatGPT account', [
        for (final entry in accounts)
          (entry.name, entry.name, '${entry.baseUrl} · ${entry.modelId}'),
        ('add', 'sign in again (re-auth)', 're-run the OAuth sign-in'),
      ]);
      if (choice == null) {
        io.writeln('ChatGPT connect cancelled');
        return;
      }
      if (choice != 'add') {
        await _switchToSavedProvider(registry!.find(choice)!);
        return;
      }
    }
  }

  final exchangeFn = config.chatGptOAuthExchangeFn ?? _defaultChatGptExchange;

  ChatGptOAuthCredentials? credentials;
  if (headless) {
    credentials = await _runChatGptHeadlessOAuth(exchangeFn: exchangeFn);
  } else {
    credentials = await runChatGptOAuthCliFlow(
      onStatus: io.writeln,
      exchangeFn: exchangeFn,
      shouldOpenBrowserFn: () =>
          shouldLaunchBrowser(noBrowserFlag: noBrowser),
    );
  }

