              fallback,
              sameBaseUrl: spec.defaultBaseUrl,
              // The alias-resolved record of the same domain may carry
              // a variant base URL — landing on it is the point of
              // alias resolution, not a name clash.
              allowClash: (clash) => clash == existing,
