/// Saves OAuth-derived ChatGPT credentials and switches to the Codex
/// backend so the session is usable at once. The account also lands in
/// the provider registry (name prompt included) like every other
/// connected provider — without the entry it never showed in `/provider`.
/// ONE identity per auth domain (issue #1706): the entry is resolved by
/// base URL / canonical name BEFORE the prompt, and the login lands on
/// it — Enter re-auths the existing entry and keeps its model, a typed
/// new name RENAMES it (the base-URL convention: rename keeps the
/// entry) and re-runs the guided model pick. The registry never grows a
/// custom-named twin of the chatgpt record; the renamed entry's
/// credentials live in its own name-scoped key slot, so a refresh-token
/// rotation never writes a slot another record reads.
Future<void> _applyChatGptOAuthCredentials(
  ProviderSpec spec,
  ChatGptOAuthCredentials credentials,
) async {
  io.writeln('ChatGPT authorized');
  final encoded = credentials.encode();
  final registry = config.customProviders;
  // Alias resolution on the write path (#706): an existing record of
  // the SAME auth domain — exact base URL or an alias spelling of the
  // provider id (`chatgpt` / `chatgpt.com`) constrained to this
  // backend's dialect or endpoint — receives this login. Minting a
  // second record for one domain is how the /model picker grew twin
  // identities both marked current; a same-named entry on another
  // backend (proxy) is NOT this domain and never receives the blob.
  final existing = registry != null
      ? (_entryForBaseUrl(registry, spec.defaultBaseUrl) ??
            _entryForCanonicalName(
              registry,
              spec.name,
              apiType: spec.name,
              baseUrl: spec.defaultBaseUrl,
            ))
      : null;
  final fallback = existing?.name ?? _codeMieHostName(spec.defaultBaseUrl);
  // A cancel keeps the fallback — the OAuth credentials are already
  // minted and stored.
  final name =
      (registry == null
          ? fallback
          : (await _askConnectProviderName(
              fallback,
              sameBaseUrl: spec.defaultBaseUrl,
              // The alias-resolved record of the same domain may carry
              // a variant base URL — landing on it is the point of
              // alias resolution, not a name clash.
              allowClash: (clash) => clash == existing,
            ))) ??
      fallback;
  // Re-auth stores into the entry's own slot (a legacy entry keeps its
  // env-name slot); a new account scopes its slot by name. A typed name
  // that differs from the resolved record is a RENAME (#1706): the old
  // record is dropped first so the domain keeps exactly one entry —
  // the edit wizard's rename shape (drop old, save under the new name).
  final renamed = existing != null && name != existing.name;
  if (renamed) {
    registry!.entries.removeWhere((e) => e.name == existing.name);
  }
  final keyName =
      registry?.find(name)?.keyName ??
      CustomProviderRegistry.keyNameFor(
        spec.defaultBaseUrl,
        providerName: name,
      );
  await _storeProviderToken(
    spec,
    spec.defaultBaseUrl,
    encoded,
    keyName: keyName,
  );

  // Guided model pick for a NEW account or a RENAME (a new name is a
  // fresh setup of the one domain entry): the live Codex /models
  // answer under the fresh credentials; cancel (or a failed/empty
  // fetch) keeps the bundled default. A re-login to the SAME entry
  // keeps its last-used model.
  final sameAccount = existing != null && name == existing.name;
  final modelId = sameAccount
      ? existing.modelId
      : (await _pickChatGptModel(spec, encoded) ?? chatGptCodexDefaultModel);

  if (registry != null) {
    // The login lands on the ONE domain record (in place — `add` both
    // re-orders and rejects reserved-named domain ghosts, #706); a
    // rename already dropped the old spelling above, so `add` saves
    // the entry under its new name (#1706 — never a second record).
    final target = registry.find(name);
    if (target == null) {
      registry.add(
        CustomProviderEntry(
          name: name,
          apiType: spec.name,
          baseUrl: spec.defaultBaseUrl,
          modelId: modelId,
          keyName: keyName,
        ),
      );
    } else {
      target
        ..modelId = modelId
        ..keyName = keyName;
    }
    _activeCustomName = name;
    io.writeln('saved provider $name (listed first in /provider)');
  }
  await _switchProvider(
    spec,
    spec.defaultBaseUrl,
    modelId,
    token: [REDACTED:Sensitive Value],
    tokenKeyName: keyName,
  );
}

/// The live Codex `/models` pick for a NEW ChatGPT account: the ids
/// under the fresh credentials, answered by
/// [AgentCliConfig.modelsFetcher] when injected (tests), else the real
/// dialect. Null = keep the bundled default.
Future<String?> _pickChatGptModel(ProviderSpec spec, String key) async {
  final List<String> ids;
  try {
    final fetch = config.modelsFetcher;
    ids = fetch != null
        ? await fetch(spec.defaultBaseUrl, apiKey: [REDACTED:Sensitive Value])
        : await _fetchProviderModelIds(spec.name, spec.defaultBaseUrl, key);
  } on Object {
    return null;
