enum CustomProviderAuthMethod {
  /// Regular API-key or env-resolved auth (default).
  apiKey,

  /// Browser-based SSO (CodeMie cookie auth).
  sso,

  /// JWT Bearer token (CodeMie headless auth).
  jwt,
