  /// `x-api-key: <key>` instead of `Authorization: Bearer <key>`.
  CustomProviderEntry({
    required this.name,
    required this.apiType,
    required this.baseUrl,
    required this.modelId,
    this.keyName,
    this.authMethod = CustomProviderAuthMethod.apiKey,
    this.authHeader,
    this.connectTimeout,
    this.streamIdleTimeout,
  });

