/// Saves OAuth-derived ChatGPT credentials and switches to the Codex
/// backend so the session is usable at once. The account also lands in
/// the provider registry (name prompt included) like every other
/// connected provider — without the entry it never showed in `/provider`.
/// ONE identity per auth domain (issue #1706): the entry is resolved by
/// base URL / canonical name BEFORE the prompt, and the login lands on
/// it — Enter re-auths the existing entry and keeps its model, a typed
/// new name RENAMES it (the base-URL convention: rename keeps the
/// entry) and re-runs the guided model pick. The registry never grows a
/// custom-named twin of the chatgpt record; the renamed entry's
/// credentials live in its own name-scoped key slot, so a refresh-token
/// rotation never writes a slot another record reads.
Future<void> _applyChatGptOAuthCredentials(
  ProviderSpec spec,
  ChatGptOAuthCredentials credentials,
) async {
  io.writeln('ChatGPT authorized');
  final encoded = credentials.encode();
  final registry = config.customProviders;
  // Alias resolution on the write path (#706): an existing record of
  // the SAME auth domain — exact base URL or an alias spelling of the
  // provider id (`chatgpt` / `chatgpt.com`) constrained to this
  // backend's dialect or endpoint — receives this login. Minting a
  // second record for one domain is how the /model picker grew twin
  // identities both marked current; a same-named entry on another
  // backend (proxy) is NOT this domain and never receives the blob.
  final existing = registry != null
      ? (_entryForBaseUrl(registry, spec.defaultBaseUrl) ??
            _entryForCanonicalName(
              registry,
              spec.name,
              apiType: spec.name,
              baseUrl: spec.defaultBaseUrl,
            ))
      : null;
  final fallback = existing?.name ?? _codeMieHostName(spec.defaultBaseUrl);
  // A cancel keeps the fallback — the OAuth credentials are already
  // minted and stored.
  final name =
      (registry == null
          ? fallback
          : (await _askConnectProviderName(
              fallback,
              sameBaseUrl: spec.defaultBaseUrl,
              // The alias-resolved record of the same domain may carry
              // a variant base URL — landing on it is the point of
              // alias resolution, not a name clash.
              allowClash: (clash) => clash == existing,
            ))) ??
      fallback;
