/// default) or no saved entry matches it.
String? authHeaderForBaseUrl(
  List<CustomProviderEntry> entries,
  String? baseUrl,
    if (sameEndpoint(entry.baseUrl, baseUrl)) return entry.authHeader;
  }
  return null;
}

