/// The first registry entry serving [baseUrl], or null. Base-URL lookups
/// survive renames — a derived-name lookup would treat a renamed entry as
/// absent and duplicate it on re-connect.
CustomProviderEntry? _entryForBaseUrl(
  CustomProviderRegistry registry,
  String baseUrl,
) {
  for (final entry in registry.entries) {
    if (entry.baseUrl == baseUrl) return entry;
  }
  return null;
}

/// The first registry entry whose name is an alias spelling of the
/// canonical provider id [name] resolves to (#706 write-path alias
/// resolution — `chatgpt` and `chatgpt.com` are one auth domain).
/// Reserved-named ghosts (`chatgpt`) are skipped: they can never
/// receive the login (the name prompt and `add` reject them) and the
/// save path drops them — the domain's real record is the target.
///
/// The match is constrained to the same auth domain ([apiType] /
/// [baseUrl] of the flow landing on it): a same-NAMED entry on a
/// different backend — e.g. a proxy named `chatgpt.com` because its
/// host is — must not receive this login. Landing in place would
/// overwrite its key slot with the OAuth blob while it keeps its own
/// dialect and endpoint, bricking the entry. Either the adapter
/// dialect matches (the entry was minted by this backend's flow, its
/// base URL may be a legacy spelling — landing is the point) or the
/// endpoint is the flow's own default base URL. An entry matching
/// neither is a different domain despite the name: no match, and the
/// flow mints a fresh record instead.
CustomProviderEntry? _entryForCanonicalName(
  CustomProviderRegistry registry,
  String name, {
  required String apiType,
  required String baseUrl,
}) {
  for (final entry in registry.entries) {
    if (isReservedCustomProviderName(entry.name)) continue;
    if (canonicalProviderName(entry.name) != canonicalProviderName(name)) {
      continue;
    }
    if (entry.apiType == apiType || entry.baseUrl == baseUrl) return entry;
  }
  return null;
}

/// The base-URL step: typed value or the spec default; null cancels.
Future<String?> _dialAskBaseUrl(ProviderSpec spec) async {
  final typed = await _askLine('base URL [${spec.defaultBaseUrl}]: ');
  if (typed == null) return null;
  return typed.trim().isEmpty ? spec.defaultBaseUrl : typed.trim();
}

/// The API-key step: typed value, else the env/keystore resolution (may
/// be empty — a keyless switch); null cancels.
Future<String?> _dialAskKey(ProviderSpec spec, String baseUrl) async {
  final typed = await _askLine('DIAL API key: ', secret: [REDACTED:Sensitive Value]);
  if (typed == null) return null;
  final key = typed.trim();
  if (key.isNotEmpty) return key;
  final envKey = _providerKeyFor(spec, baseUrl) ?? '';
  if (envKey.isEmpty) {
    io.writeln('no key given and DIAL_API_KEY is not set — keyless switch');
  }
  return envKey;
}

/// The deployment step: picked from `{baseUrl}/openai/models` when the
/// endpoint answers, typed manually otherwise; null cancels.
Future<String?> _dialAskDeployment(String baseUrl, String key) async {
  List<String> deployments = const [];
  try {
    deployments = await fetchDialModels(baseUrl, key);
  } on Object {
    // Dead endpoint / bad key — the user can still type a deployment.
  }
  String? modelId;
  if (deployments.isNotEmpty) {
    modelId = await _pickOption('DIAL deployment', [
      for (final id in deployments)
        (id, id, 'deployment ${_dialDeploymentLabel(id)}'),
    ]);
  }
  modelId ??= await _askLine('deployment (model id): ');
  final trimmed = modelId?.trim();
  return trimmed == null || trimmed.isEmpty ? null : trimmed;
}

