Future<String?> _dialAskBaseUrl(ProviderSpec spec) async {
  final typed = await _askLine('base URL [${spec.defaultBaseUrl}]: ');
  if (typed == null) return null;
  return typed.trim().isEmpty ? spec.defaultBaseUrl : typed.trim();
}

