Future<String?> _dialAskDeployment(String baseUrl, String key) async {
  List<String> deployments = const [];
  try {
    deployments = await fetchDialModels(baseUrl, key);
  } on Object {
    // Dead endpoint / bad key — the user can still type a deployment.
