  if (key.isNotEmpty) return key;
  final envKey = _providerKeyFor(spec, baseUrl) ?? '';
  if (envKey.isEmpty) {
    io.writeln('no key given and DIAL_API_KEY is not set — keyless switch');
  }
  return envKey;
}

